feedbackvariables.text:
/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte de la chaîne */
test_exact:is(ssearch("zone_sys:Chien", ans1) # false);
/* On crée une liste des mots attendus pour la suite */
mots_attendus: ["Air", "Terre"];

/* On vérifie si TOUS les mots sont présents dans la réponse */
tous_presents: all_listp(lambda([x], ssearch(x, ans1) # false), mots_attendus);


/* pour les flèches*/
/* On vérifie la présence exacte des chaînes pour les objets */
test_fleche1 : is(
    (ssearch("Sol-Chien-solid", ans1) # false) or 
    (ssearch("Chien-Sol-solid", ans1) # false)
);
test_fleche1_wrong : is(
    (ssearch("Sol-Chien-dashed", ans1) # false) or 
    (ssearch("Chien-Sol-dashed", ans1) # false)
);

/* Test pour la flèche entre Air et voiture (les deux sens acceptés) */
test_fleche2 : is(
    (ssearch("Air-Chien-solid", ans1) # false) or 
    (ssearch("Chien-Air-solid", ans1) # false)
);
test_fleche2_wrong : is(
    (ssearch("Air-Chien-dashed", ans1) # false) or 
    (ssearch("Chien-Air-dashed", ans1) # false)
);

/* Test pour la flèche entre Chien et Terre (les deux sens acceptés) */
test_fleche3 : is(
    (ssearch("Chien-Terre-dashed", ans1) # false) or 
    (ssearch("Terre-Chien-dashed", ans1) # false)
);
test_fleche3_wrong : is(
    (ssearch("Chien-Terre-solid", ans1) # false) or 
    (ssearch("Terre-Chien-solid", ans1) # false)
);

/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte des chaines nip enlevées*/
test_1:is(ssearch("nipsiffletd'appel", ans1) # false);
test_2:is(ssearch("nipphotographe", ans1) # false);
/*On verifie que tout les hors système sont présents */
tous_hors_sys_ok: test_1 and test_2 ;
